def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    post_d_c = 0
    post_d_d = 0
    post_c_c = 0
    post_c_d = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        curr_opp = history[i][1]
        if prev_my == 'D':
            if curr_opp == 'C':
                post_d_c += 1
            else:
                post_d_d += 1
        elif prev_my == 'C':
            if curr_opp == 'C':
                post_c_c += 1
            else:
                post_c_d += 1

    last_my, last_opp = history[-1]

    my_d_run = 0
    for i in reversed(range(n)):
        if history[i][0] == 'D':
            my_d_run += 1
        else:
            break

    my_c_run = 0
    for i in reversed(range(n)):
        if history[i][0] == 'C':
            my_c_run += 1
        else:
            break

    opp_d_run = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    opp_c_run = 0
    for i in reversed(range(n)):
        if history[i][1] == 'C':
            opp_c_run += 1
        else:
            break

    recent_start = max(0, n - 4)
    recent_my_d = 0
    for i in range(recent_start, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    recent_opp_d = sum(1 for a, b in history[-5:] if b == 'D')
    recent_opp_c = min(5, n) - recent_opp_d

    hostile = (
        opp_d * 10 >= n * 7 and
        (post_c_c * 2 <= post_c_d or opp_c_run < 2)
    )

    recoverable = not hostile and (
        (opp_d * 10 <= n * 5) or
        (post_c_c >= 2 and post_c_c >= post_c_d) or
        (opp_c_run >= 5 and recent_opp_d <= 2)
    )

    exploitable = (
        post_d_c >= 3 and
        post_d_c >= post_d_d and
        opp_d * 10 <= n * 6
    )

    if hostile:
        return 'D'

    if exploitable:
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recoverable:
                if my_d_run >= 2:
                    return 'C'
                return 'D'
            return 'D'
        else:
            if recoverable:
                if recent_my_d == 0:
                    return 'D'
                if my_c_run <= 4:
                    return 'C'
                return 'D'
            return 'D'

    if recoverable and my_d == 0 and opp_d == 0 and n >= 20 and n < 90:
        return 'D'

    if (
        recoverable and
        3 <= opp_d <= 5 and
        post_d_c == 0 and
        opp_c_run >= 3 and
        my_c_run >= 3 and
        recent_my_d == 0 and
        n >= 18 and
        n < 90
    ):
        return 'D'

    if (
        recoverable and
        opp_d * 10 <= n * 4 and
        recent_opp_d == 0 and
        opp_c_run >= 10 and
        my_c_run >= 10 and
        recent_opp_c >= 5 and
        n < 90
    ):
        if rng.random() < 0.03:
            return 'D'

    return 'C'
